  'Deze afbeelding naar het AI-model sturen?': 'Poslati ovu sliku AI modelu?',
  'De afbeelding gaat ongewijzigd naar':
      'Slika će nepromijenjena biti poslana na',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck ništa ne redigira unutar slike: lica, tekst na snimci zaslona i vidljivi podaci šalju se zajedno.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Provjera slika ovdje je pronašla jedno ili više prepoznatljivih lica.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Uz izvoz nastaju dvije datoteke pomoću kojih primatelj može provjeriti redakcije.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'navodi što je izostavljeno, bez samih vrijednosti. Ova datoteka smije ići uz izvještaj.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'sadrži ključeve kojima se svaka redigirana vrijednost može ponovno izračunati. Ne šaljite ovu datoteku: time je redakcija poništena. Čuvajte je uz izvor.',
  'slides': 'slajdovi',
  'Achtergehouden': 'Zadržano',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Zadržano: klasificirano strože od prezentacije',
  '1 slide achtergehouden door haar TLP': '1 slajd zadržan zbog svog TLP-a',
  'slides achtergehouden door hun TLP': 'slajdova zadržano zbog njihova TLP-a',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Ovi se slajdovi ne uključuju pri prezentiranju, izvozu ni u paketu. Povisite razinu TLP prezentacije u Informacijama o prezentaciji da biste ih uključili.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Svi su slajdovi zadržani zbog svoje TLP klasifikacije pa nema što prikazati.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Svi su slajdovi zadržani zbog svoje TLP klasifikacije pa nema što izvesti.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Svi su slajdovi preskočeni ili zadržani zbog svoje TLP klasifikacije pa nema što prikazati.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Svi su slajdovi preskočeni ili zadržani zbog svoje TLP klasifikacije pa nema što izvesti.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Brojke grafikona nisu spremljene — postoje još samo u ovom prozoru:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'U pregledniku nema oporavka nakon rušenja: zatvorite li ovu karticu, nespremljeni rad nestaje. Sami spremite svoju prezentaciju.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Lokalna baza CVE (preuzimanje pokrećete sami): OciDeck dohvaća skupne podatke preko api.github.com i datoteke izdanja na koju ta adresa upućuje.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Pretraživanje CVE-a (prema zadanome isključeno): kada je uključeno, vaš pojam za pretraživanje ide na postavljeno CVE zrcalo, a ako ono ništa ne nađe — u europsku bazu ENISA-e i u MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Ugrađeni YouTube ili Vimeo videozapis učitava reproduktor s te usluge.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  U pregledniku: ako preglednik odbije izravno dohvatiti adresu, OciDeck pokušava ponovno preko poslužitelja s kojega je aplikacija došla; ta adresa tada stiže do toga poslužitelja.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Povlačenje nije spremljeno. Pri sljedećem pokretanju vaša privola ponovno vrijedi.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Naslov odjeljka koji najavljuje novi dio prezentacije. Neka bude kratak. Iz knjižnice slika dodajte pozadinsku sliku.',
  'Bronnen doorzoeken…': 'Pretraživanje izvora…',
  'Niet doorzocht': 'Nije pretraženo',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ova se provjera ne izvodi u web verziji: prepoznavanje lica zahtijeva sistemsku biblioteku koju preglednik nema. Upotrijebite verziju za računalo da provjerite lica na slikama.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Token treba prava čitanja i pisanja u repozitorij. Gitea i Forgejo nemaju pretraživanje na poslužitelju; OciDeck pretražuje lokalno.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Token treba opseg repo (ili detaljno: Contents čitanje i pisanje).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Token treba read_repository, write_repository i read_api. Pretraživanje na poslužitelju zahtijeva Advanced ili Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Brzo pretraživanje na poslužitelju — zbog kašnjenja indeksiranja nedavno promijenjen špil može nedostajati.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Medijski sadržaj ne čuva se u običnoj .md datoteci',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Slike, videozapisi i zvuk koje ste odabrali na ovoj kartici postoje samo u memoriji. Obična .md datoteka ih ne čuva — nestat će kad je ponovno otvorite. Izvezite kao .ocideck paket da ponesete medijski sadržaj sa sobom.',
  'Media verwijderd om privacyredenen':
      'Medijski sadržaj uklonjen radi privatnosti',
