  'Geen instelling gevonden': 'Nije pronađena nijedna postavka',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Vaš pojam za pretraživanje šalje se konfiguriranom CVE zrcalu, a ako ono ništa ne pronađe, i ENISA-i i MITRE-u. Tko upravlja tim poslužiteljima može zaključiti koju konkretnu ranjivost tražite — a time i koju ranjivost istražujete.',
  'Accepteren': 'Prihvati',
  'Accepteren + waarschuwen': 'Prihvati + upozori',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Prihvati: podaci ovdje pripadaju i obavijest nestaje. Prihvati + upozori: primatelj vidi oznaku da slajd sadrži osobne podatke. Izostavi: pronađeni podaci postaju nečitljivi na zaslonu i u izvozu — tvoja Markdown datoteka zadržava izvorni tekst.',
  'Alleen melden': 'Samo prijavi',
  'PERSOONSGEGEVENS': 'OSOBNI PODACI',
  'Persoonsgegevens op deze slide': 'Osobni podaci na ovom slajdu',
  'Volg de presentatie': 'Prati prezentaciju',
  'Weglaten uit tonen en exporteren': 'Izostavi iz prikaza i izvoza',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Razmisli o redigiranju pomoću [[dvostrukih uglatih zagrada]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Bez konteksta u tekstu ovo možda uopće nije osobni podatak.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Pregledava tvoje slajdove tražeći identifikacijske brojeve, kontaktne podatke i druge osjetljive podatke te ih prijavljuje u provjeri kvalitete. To se u cijelosti događa na ovom uređaju; ništa se ne šalje. To je pomagalo, a ne jamstvo: tekst u slikama i podaci bez prepoznatljivog obrasca ostaju izvan vidokruga.',
  'Mogelijk persoonsgegeven': 'Mogući osobni podatak',
  'Privacycontrole': 'Provjera privatnosti',
  'Waarschuw bij mogelijke persoonsgegevens':
